import { msg, t } from './i18n';
import { useState, type FormEvent, type ReactNode } from 'react';
import { Download, ExternalLink, Plus, Trash2, Check, AlertCircle, CheckCircle2 } from 'lucide-react';
import { EXPENSE_CATEGORIES, EXPENSE_VAT, PAYMENT_METHODS, PROJECT_STATUSES, TIME_CATEGORIES, type AppState, type BusinessProfile, type DraftInput, type ExpenseInput, type ExpenseVat, type ProjectStatus, type Upload, type VatFiling } from '../shared/types';
import { isEu } from '../shared/geo';
import { download, fileUpload } from './api';
import { Button, Check as CheckField, Field, Modal } from './components';
import { bytes, countries, country, currencies, date, decimal, dueDate, duration, expenseVatLabels, localDate, money, statusLabels, today } from './format';
import type { ModalName, OpenModal, Run } from './pages';

type Props = { state: AppState; run: Run; busy: boolean; onClose: () => void; open: OpenModal; id?: string; projectId?: string; onInvoice: (id: string) => void; };
const text = (data: FormData, name: string) => String(data.get(name) ?? '').trim();
const checked = (data: FormData, name: string) => data.get(name) === 'on';
// The API expects a decimal point; accept a typed decimal comma ("150,50") as the same value.
const decimalText = (data: FormData, name: string) => text(data, name).replace(',', '.');
function Country({ value = 'NL', name = 'country', optional = false }: { value?: string; name?: string; optional?: boolean }) { return <select name={name} defaultValue={value}>{optional && <option value="">{t("Not specified")}</option>}{countries.map(([code, label]) => <option value={code} key={code}>{label}</option>)}<option value="ZZ">{t("Other / not listed")}</option></select>; }
function Currency({ name = 'currency', value, defaultValue, onChange, disabled }: { name?: string; value?: string; defaultValue?: string; onChange?: (value: string) => void; disabled?: boolean }) { return <select name={name} value={value} defaultValue={value === undefined ? defaultValue : undefined} disabled={disabled} onChange={event => onChange?.(event.target.value)}>{currencies.map(([code, label]) => <option value={code} key={code}>{code} · {label}</option>)}</select>; }
/** Suggestions only: any short text is accepted, so you can keep your own categories. */
function Suggestions({ id, values }: { id: string; values: readonly string[] }) { return <datalist id={id}>{[...new Set(values)].filter(Boolean).map(value => <option key={value} value={value}/>)}</datalist>; }
const clock = (value: string) => /^\d{2}:\d{2}$/.test(value) ? Number(value.slice(0, 2)) * 60 + Number(value.slice(3)) : null;
/** Customer country decides the VAT path: domestic, EU reverse charge, or outside the EU. */
function treatmentOf(code: string | undefined) { return code === 'NL' ? 'domestic' : !code || code === 'ZZ' ? 'unknown' : isEu(code) ? 'eu' : 'outside'; }
function ProjectSelect({ state, value, onChange }: { state: AppState; value?: string; onChange?: (value: string) => void }) { return <select name="projectId" required value={onChange ? value : undefined} defaultValue={onChange ? undefined : value || state.projects[0]?.id} onChange={event => onChange?.(event.target.value)}>{state.projects.map(project => <option value={project.id} key={project.id}>{project.name} · {state.clients.find(client => client.id === project.clientId)?.name}</option>)}</select>; }
function Amount({ name, value = '', required = true, placeholder = '0.00' }: { name: string; value?: string; required?: boolean; placeholder?: string }) { return <input name={name} defaultValue={value} required={required} inputMode="decimal" pattern="[0-9]{1,10}([.,][0-9]{1,2})?" title={t("An amount such as 150.00")} placeholder={placeholder}/>; }
function Form({ children, onSubmit, busy, onClose, label = t("Save"), hint }: { children: ReactNode; onSubmit: (data: FormData) => Promise<boolean>; busy: boolean; onClose: () => void; label?: string; hint?: string }) {
  const [error, setError] = useState('');
  const [working, setWorking] = useState(false);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (working || busy) return;
    const data = new FormData(event.currentTarget); setWorking(true); setError('');
    try { if (await onSubmit(data)) onClose(); } catch (error) { setError(error instanceof Error ? t(error.message) : t("Could not save. Please try again.")); }
    finally { setWorking(false); }
  }
  return <form onSubmit={submit}><fieldset disabled={busy || working}>{children}</fieldset>{error && <p className="form-error" role="alert"><AlertCircle size={16}/><span>{error}{' '}{t("Your input is kept.")}</span></p>}{hint && <p className="form-footnote">{hint}</p>}<div className="form-actions"><Button type="button" variant="secondary" onClick={onClose} disabled={busy || working}>{t("Cancel")}</Button><Button type="submit" disabled={busy || working}>{working || busy ? t("Saving…") : label}</Button></div></form>;
}

/** Flags a record that changed (or vanished) after this form opened, e.g. in another tab, so a save never silently overwrites it. */
// Whole sentences per record type, so each language can use its own grammar.
const changedText = {
  client: [msg('This client no longer exists.'), msg('This client was changed in another window while you were editing.')],
  project: [msg('This project no longer exists.'), msg('This project was changed in another window while you were editing.')],
  'time entry': [msg('This time entry no longer exists.'), msg('This time entry was changed in another window while you were editing.')],
  expense: [msg('This expense no longer exists.'), msg('This expense was changed in another window while you were editing.')],
  'business profile': [msg('This business profile no longer exists.'), msg('This business profile was changed in another window while you were editing.')],
};
function Changed<T extends { revision: number }>({ opened, current, noun, fields }: { opened: T | undefined; current: T | undefined; noun: keyof typeof changedText; fields: [keyof T, string, ((value: T[keyof T]) => string)?][] }) {
  if (!opened) return null;
  if (!current) return <div className="notice amber" role="alert"><strong>{t(changedText[noun][0])}</strong><p>{t("It was deleted in another window. Close this form; nothing will be saved.")}</p></div>;
  if (current.revision === opened.revision) return null;
  const show = (value: unknown) => typeof value === 'boolean' ? (value ? 'yes' : 'no') : String(value ?? '—').slice(0, 80);
  const changes = fields.filter(([key]) => JSON.stringify(opened[key]) !== JSON.stringify(current[key]));
  return <div className="notice amber" role="alert"><strong>{t(changedText[noun][1])}</strong><p>{t("Your edits are still in the form. Saving now replaces the newer saved version")}{changes.length ? ':' : '.'}</p>{changes.length > 0 && <ul>{changes.map(([key, label, format]) => <li key={String(key)}>{label}{' '}{t("is now “")}{format ? format(current[key]) : show(current[key])}”</li>)}</ul>}</div>;
}

function ClientForm(props: Props) {
  const client = props.state.clients.find(client => client.id === props.id);
  const [opened] = useState(client);
  return <Form {...props} label={opened ? t("Save client") : t("Create client")} onSubmit={async data => {
    if (opened && !client) throw new Error(t("This client no longer exists."));
    const input = { name: text(data, 'name'), address: text(data, 'address'), country: text(data, 'country'), email: text(data, 'email'), taxId: text(data, 'taxId'), contactName: text(data, 'contactName'), registrationId: text(data, 'registrationId'), notes: text(data, 'notes') };
    return !!await props.run(client ? { type: 'client.update', data: { ...input, id: client.id, revision: client.revision } } : { type: 'client.create', data: input });
  }}><Changed opened={opened} current={client} noun="client" fields={[['name', t("Name")], ['contactName', t("Contact person")], ['address', t("Address")], ['country', t("Country"), value => country(String(value))], ['email', t("Email")], ['taxId', t("Tax ID")], ['registrationId', t("Registration")], ['notes', t("Notes")]]}/><div className="form-grid"><Field label={t("Client / company name")}><input name="name" defaultValue={client?.name} required maxLength={160} placeholder={t("e.g. Paper Plane Studio")}/></Field><Field label={t("Attention of")} hint={t("Printed on invoices as “Attn.”")}><input name="contactName" defaultValue={client?.contactName} maxLength={200} placeholder={t("Contact person")}/></Field><Field label={t("Billing address")} className="full"><textarea name="address" maxLength={4000} defaultValue={client?.address} rows={3} placeholder={t("Street, postal code and city")}/></Field><Field label={t("Country")} hint={t("Decides the VAT treatment of invoices.")}><Country value={client?.country}/></Field><Field label={t("Contact email")}><input name="email" defaultValue={client?.email} type="email" placeholder="hello@example.com"/></Field><Field label={t("Tax / VAT ID")} hint={t("Required for EU reverse-charge invoices.")}><input name="taxId" maxLength={100} defaultValue={client?.taxId} placeholder={t("Optional customer VAT ID")}/></Field><Field label={t("Business registration")} hint={t("e.g. KvK or company number")}><input name="registrationId" maxLength={100} defaultValue={client?.registrationId} placeholder={t("Optional")}/></Field><Field label={t("Notes")} className="full"><textarea name="notes" rows={2} maxLength={4000} defaultValue={client?.notes} placeholder={t("Private notes; not printed")}/></Field></div></Form>;
}
function ProjectForm(props: Props) {
  const project = props.state.projects.find(project => project.id === props.id);
  const [opened] = useState(project);
  const [kind, setKind] = useState(project?.kind || 'hourly');
  const currency = props.state.workspace.currency;
  if (!props.state.clients.length) return <div className="form-body"><p>{t("First, add the client this project belongs to. Then you can set its price and start tracking work.")}</p><Button icon={Plus} onClick={() => props.open('client')}>{t("Create a client")}</Button></div>;
  return <Form {...props} label={opened ? t("Save project") : t("Create project")} onSubmit={async data => {
    if (opened && !project) throw new Error(t("This project no longer exists."));
    const input = { clientId: text(data, 'clientId'), name: text(data, 'name'), kind, rate: kind === 'hourly' ? decimalText(data, 'rate') : '0', fixedPrice: kind === 'fixed' ? decimalText(data, 'fixedPrice') : null, costsComplete: checked(data, 'costsComplete'), status: text(data, 'status') as ProjectStatus, estimatedRemainingMinutes: text(data, 'estimatedRemainingMinutes') ? Number(text(data, 'estimatedRemainingMinutes')) : null, notes: text(data, 'notes') };
    return !!await props.run(project ? { type: 'project.update', data: { ...input, id: project.id, revision: project.revision } } : { type: 'project.create', data: input });
  }}><Changed opened={opened} current={project} noun="project" fields={[['name', t("Name")], ['clientId', t("Client"), value => props.state.clients.find(client => client.id === value)?.name || '—'], ['kind', t("Pricing")], ['rateMinor', t("Hourly rate"), value => money(Number(value), currency)], ['fixedPriceMinor', t("Fixed price"), value => money(value as number | null, currency)], ['status', t("Status"), value => statusLabels[String(value)]], ['costsComplete', t("Costs complete")], ['notes', t("Notes")]]}/><div className="form-grid"><Field label={t("Project name")} className="full"><input name="name" required defaultValue={project?.name} placeholder={t("e.g. Brand launch")} maxLength={160}/></Field><Field label={t("Client")} className="full"><select name="clientId" defaultValue={project?.clientId || props.state.clients[0].id}>{props.state.clients.map(client => <option key={client.id} value={client.id}>{client.name}</option>)}</select></Field><Field label={t("How do you charge?")}><select value={kind} onChange={event => setKind(event.target.value as 'hourly' | 'fixed')}><option value="hourly">{t("Hourly rate")}</option><option value="fixed">{t("Fixed project price")}</option></select></Field><Field label={kind === 'hourly' ? t("Hourly rate ({0})", currency) : t("Full contract, before tax ({0})", currency)}><Amount key={kind} name={kind === 'hourly' ? 'rate' : 'fixedPrice'} value={project ? decimal(kind === 'hourly' ? project.rateMinor : project.fixedPriceMinor || 0) : ''}/></Field><Field label={t("Project status")}><select name="status" defaultValue={project?.status || 'active'}>{PROJECT_STATUSES.map(status => <option key={status} value={status}>{statusLabels[status]}</option>)}</select></Field><Field label={t("Estimated remaining minutes")} hint={t("Optional; leave blank if unknown.")}><input name="estimatedRemainingMinutes" type="number" min="0" step="1" defaultValue={project?.estimatedRemainingMinutes ?? ''} placeholder={t("Unknown")}/></Field><Field label={t("Notes")} className="full"><textarea name="notes" rows={2} maxLength={4000} defaultValue={project?.notes} placeholder={t("Scope, agreements, planning")}/></Field></div><div className="form-callout"><CheckField name="costsComplete" defaultChecked={project?.costsComplete || false}><strong>{t("All direct costs are recorded")}</strong><small>{t("Confirm this when costs are complete, including a deliberate zero. This unlocks contribution calculations.")}</small></CheckField></div>{kind === 'fixed' && <p className="form-footnote">{t("Time measures effort on a fixed project. It is never billed again as additional hourly work.")}</p>}{project && <p className="form-footnote">{t("A new hourly rate applies to time you record from now on. Saved time keeps its rate, and issued invoices preserve their original prices and details.")}</p>}</Form>;
}
function TimeForm(props: Props) {
  const entry = props.state.timeEntries.find(entry => entry.id === props.id);
  const [opened] = useState(entry);
  const [workDate, setWorkDate] = useState(entry?.date || today());
  const [start, setStart] = useState(entry?.startTime || '');
  const [end, setEnd] = useState(entry?.endTime || '');
  const future = workDate > today();
  const from = clock(start), to = clock(end);
  const session = from !== null && to !== null ? to - from : null;
  return <Form {...props} label={opened ? t("Save time") : t("Log time")} onSubmit={async data => {
    if (opened && !entry) throw new Error(t("This time entry was deleted in another window."));
    if (session !== null && session <= 0) throw new Error(t("The end time must be after the start time on the same day."));
    const input = { projectId: text(data, 'projectId'), date: text(data, 'date'), minutes: session ?? Number(text(data, 'minutes')), description: text(data, 'description'), category: text(data, 'category'), billable: checked(data, 'billable'), approved: checked(data, 'approved'), startTime: start || null, endTime: end || null, notes: text(data, 'notes') };
    return !!await props.run(entry ? { type: 'time.update', data: { ...input, id: entry.id, revision: entry.revision } } : { type: 'time.create', data: input });
  }}><Changed opened={opened} current={entry} noun="time entry" fields={[['projectId', t("Project"), value => props.state.projects.find(project => project.id === value)?.name || '—'], ['date', t("Date"), value => date(String(value))], ['minutes', t("Duration"), value => duration(Number(value))], ['description', t("Description")], ['category', t("Category")], ['billable', t("Billable")], ['approved', t("Approved")]]}/><div className="form-grid"><Field label={t("Project")} className="full"><ProjectSelect state={props.state} value={entry?.projectId || props.projectId}/></Field><Field label={t("Work date")}><input type="date" name="date" required value={workDate} onChange={event => setWorkDate(event.target.value)}/></Field><Field label={t("Minutes worked")} hint={session !== null ? t("Calculated from start and end.") : t("Or fill in start and end; 90 minutes = 1h 30m.")}>{session !== null ? <input key="session" value={session > 0 ? session : ''} readOnly placeholder={t("End before start")} aria-live="polite"/> : <input key="manual" type="number" name="minutes" required min="1" max="1440" step="1" defaultValue={entry?.minutes} placeholder="60"/>}</Field><Field label={t("Start (optional)")}><input type="time" value={start} onChange={event => setStart(event.target.value)}/></Field><Field label={t("End (optional)")}><input type="time" value={end} onChange={event => setEnd(event.target.value)}/></Field><Field label={t("What did you work on?")} className="full"><textarea name="description" required rows={2} defaultValue={entry?.description} placeholder={t("e.g. Preparing the client workshop")} maxLength={200}/></Field><Field label={t("Work category")} hint={t("Pick a suggestion or type your own.")}><input name="category" required maxLength={60} list="time-categories" defaultValue={entry?.category || 'Delivery'}/><Suggestions id="time-categories" values={[...TIME_CATEGORIES, ...props.state.timeEntries.map(item => item.category)]}/></Field><Field label={t("Participants / notes")} hint={t("Not printed on invoices.")}><input name="notes" maxLength={4000} defaultValue={entry?.notes} placeholder={t("Optional")}/></Field></div><div className="checks"><CheckField name="billable" defaultChecked={entry?.billable ?? true}>{t("Billable work")}</CheckField>{future ? <CheckField key="future" disabled checked={false} readOnly><span>{t("Future work is saved as an unapproved proposal. Approve it once the work is done.")}</span></CheckField> : <CheckField key="actual" name="approved" defaultChecked={entry?.approved ?? true}><span>{t("I confirm this duration and billing choice")}</span></CheckField>}</div><p className="form-footnote">{t("Preparation, meetings and aftercare are real work, even when you don't bill them. Unapproved entries are not counted or invoiced until you confirm them.")}</p></Form>;
}
function TimerForm(props: Props) {
  return <Form {...props} label={t("Start timer")} onSubmit={async data => !!await props.run({ type: 'timer.start', data: { projectId: text(data, 'projectId'), description: text(data, 'description'), category: text(data, 'category'), billable: checked(data, 'billable') } })}><div className="form-grid"><Field label={t("Project")} className="full"><ProjectSelect state={props.state} value={props.projectId}/></Field><Field label={t("What are you working on?")} className="full"><input name="description" required placeholder={t("A short description")} maxLength={200}/></Field><Field label={t("Work category")} className="full"><input name="category" required maxLength={60} list="timer-categories" defaultValue="Delivery"/><Suggestions id="timer-categories" values={[...TIME_CATEGORIES, ...props.state.timeEntries.map(item => item.category)]}/></Field></div><div className="checks"><CheckField name="billable" defaultChecked>{t("Billable work")}</CheckField></div><p className="form-footnote">{t("The start time is saved on this computer, so the timer survives a restart. When you stop, review the duration before saving it as actual work.")}</p></Form>;
}
/**
 * Decides when a stopped timer should NOT be pre-approved. Elapsed wall-clock time is only a suggestion:
 * a laptop asleep overnight or a forgotten timer must not quietly become billable work.
 * Trade-off: a lower threshold means more manual confirmations for genuine long sessions.
 */
function needsDurationReview(elapsedMinutes: number, started: Date, now: Date): boolean {
  return elapsedMinutes > 4 * 60 || localDate(started) !== localDate(now);
}
function StopTimerForm(props: Props) {
  const timer = props.state.timer;
  if (!timer) return <div className="form-body"><p>{t("This timer was already stopped, possibly in another window. Its time is in your ledger if it was saved.")}</p><div className="form-actions"><Button variant="secondary" onClick={props.onClose}>{t("Close")}</Button></div></div>;
  const started = new Date(timer.startedAt);
  const elapsed = Math.max(1, Math.round((Date.now() - started.getTime()) / 60000));
  const review = needsDurationReview(elapsed, started, new Date());
  return <Form {...props} label={t("Save time")} onSubmit={async data => !!await props.run({ type: 'timer.stop', data: { minutes: Number(text(data, 'minutes')), date: text(data, 'date'), approved: checked(data, 'approved') } })}><div className="form-body"><div className="timer-review"><ClockFace/><div><strong>{duration(elapsed)}{' '}{t("elapsed")}</strong><p>{t("Started")}{' '}{started.toLocaleString([], { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}{t(". Adjust for breaks, sleep or time away. Elapsed time is only a suggestion.")}</p></div></div>{review && <div className="notice amber" role="alert"><strong>{t("Long or overnight session.")}</strong><p>{t("This may include time you weren't working. Enter the minutes you actually worked, then confirm them yourself.")}</p></div>}<div className="form-grid"><Field label={t("Actual minutes worked")}><input name="minutes" type="number" required min="1" max="1440" step="1" defaultValue={Math.min(elapsed, 1440)}/></Field><Field label={t("Work date")}><input name="date" type="date" defaultValue={localDate(started)} max={today()} required/></Field></div><CheckField name="approved" defaultChecked={!review}>{t("I confirm the actual duration")}</CheckField><p className="form-footnote">{t("Leave unconfirmed to keep it in “Needs review”; it won't count as work until approved.")}</p></div></Form>;
}
function ClockFace() { return <span className="clock-face" aria-hidden="true">◷</span>; }

function DraftForm(props: Props) {
  const available = (id: string) => props.state.timeEntries.filter(entry => entry.projectId === id && entry.approved && entry.billable && !entry.invoiceId);
  const base = props.state.workspace.currency;
  const [projectId, setProject] = useState(props.projectId || props.state.projects.find(project => project.kind === 'hourly' && available(project.id).length)?.id || props.state.projects[0]?.id || '');
  const [selection, setSelection] = useState<string[]>(available(projectId).map(entry => entry.id));
  const [extraLines, setExtraLines] = useState<number[]>([]);
  const [currency, setCurrency] = useState(base);
  const project = props.state.projects.find(project => project.id === projectId);
  const client = props.state.clients.find(client => client.id === project?.clientId);
  const treatment = treatmentOf(client?.country);
  const defaultRate = treatment === 'domestic' || treatment === 'unknown' ? props.state.business.defaultTaxRate : '0';
  const entries = available(projectId);
  const reserved = props.state.timeEntries.filter(entry => entry.projectId === projectId && entry.invoiceId).length;
  const fixed = project?.kind === 'fixed';
  const fixedInvoiced = fixed && props.state.invoices.some(invoice => invoice.projectId === projectId);
  return <Form {...props} label={t("Create draft")} onSubmit={async data => {
    // A fixed contract is one line: its tracked time stays unallocated to measure effort, and extra charges belong elsewhere.
    const lines: DraftInput['extraLines'] = fixed ? [] : extraLines.map(key => ({ description: text(data, `description-${key}`), quantity: decimalText(data, `quantity-${key}`), unitPrice: decimalText(data, `unitPrice-${key}`), taxRate: decimalText(data, `taxRate-${key}`) }));
    const result = await props.run({ type: 'invoice.draft', data: { projectId, timeEntryIds: fixed ? [] : selection, issueDate: text(data, 'issueDate'), supplyDate: text(data, 'supplyDate'), dueDate: text(data, 'dueDate'), taxRate: decimalText(data, 'taxRate'), notes: text(data, 'notes'), extraLines: lines, currency, exchangeRate: currency === base ? undefined : decimalText(data, 'exchangeRate') } });
    if (result?.createdId) props.onInvoice(result.createdId);
    return !!result;
  }}><div className="form-grid"><Field label={t("Project")} className="full"><ProjectSelect state={props.state} value={projectId} onChange={id => { setProject(id); setSelection(available(id).map(entry => entry.id)); }}/></Field><Field label={t("Invoice date")}><input type="date" name="issueDate" defaultValue={today()} required/></Field><Field label={t("Supply date")}><input type="date" name="supplyDate" defaultValue={today()} required/></Field><Field label={t("Payment due")}><input type="date" name="dueDate" defaultValue={dueDate()} required/></Field><Field label={t("Tax rate (%)")} hint={treatment === 'domestic' ? t("Netherlands: 21% standard or 9% reduced.") : treatment === 'unknown' ? t("Set the customer country to know the VAT treatment.") : t("No Netherlands VAT for this customer: 0%.")}><input key={`rate-${treatment}`} name="taxRate" required defaultValue={defaultRate} inputMode="decimal" pattern="[0-9]{1,3}([.,][0-9]{1,3})?" title={t("A percentage such as 21 or 8.875")}/></Field><Field label={t("Invoice currency")}><Currency value={currency} onChange={setCurrency}/></Field>{currency !== base && <Field label={t("Exchange rate · 1 {0} =", base)} hint={t("How many {0} for 1 {1} on the invoice date. Prices convert once; reports stay in {2}.", currency, base, base)}><input name="exchangeRate" required inputMode="decimal" pattern="[0-9]{1,7}([.,][0-9]{1,6})?" placeholder={t("e.g. 1.0850")} title={t("Up to six decimals")}/></Field>}</div>{client && treatment !== 'domestic' && <div className={`notice ${treatment === 'unknown' ? 'amber' : ''}`}><strong>{treatment === 'eu' ? t("EU business customer · {0}", country(client.country)) : treatment === 'outside' ? t("Customer outside the EU · {0}", country(client.country)) : t("Customer country not set")}</strong><p>{treatment === 'eu' ? t("VAT is reverse-charged to the customer. Use 0%; the invoice states “VAT reverse-charged” with their VAT ID{0}.", client.taxId ? ` (${client.taxId})` : t(", which is still missing")) : treatment === 'outside' ? t("Services to customers outside the EU carry no Netherlands VAT. Use 0%; the invoice says so.") : t("Choose the customer country in the client details before issuing.")}</p></div>}{fixed && (fixedInvoiced ? <div className="notice amber"><strong>{t("This fixed contract already has an invoice.")}</strong><p>{t("A fixed price is billed once. Delete its existing draft first, or record extra agreed work on a separate project.")}</p></div> : <div className="notice green"><strong>{t("Fixed contract ·")}{' '}{money(project.fixedPriceMinor, base)}</strong><p>{t("The draft has one line for the full agreed price")}{currency !== base ? t(", converted to {0}", currency) : ''}{t(". Hours tracked on this project are not added; they stay on the project to measure effort and contribution per hour.")}</p></div>)}{!fixed && <><div className="form-section-heading"><h3>{t("Approved, unallocated time")}</h3><span>{entries.length}{' '}{t("available")}{reserved ? t(" · {0} already held by another invoice", reserved) : ''}</span></div>{entries.length ? <div className="time-selection">{entries.map(entry => <label key={entry.id}><input type="checkbox" checked={selection.includes(entry.id)} onChange={event => setSelection(ids => event.target.checked ? [...ids, entry.id] : ids.filter(id => id !== entry.id))}/><span><strong>{entry.description}</strong><small>{date(entry.date)} · {entry.category}</small></span><strong>{duration(entry.minutes)}</strong></label>)}</div> : <p className="form-footnote">{t("No approved billable time is available for this project. Approve time in the Time screen, or add a separate invoice line below.")}</p>}<div className="form-section-heading"><h3>{t("Additional lines")}</h3><Button type="button" variant="quiet" icon={Plus} onClick={() => setExtraLines(lines => [...lines, Date.now()])}>{t("Add line")}</Button></div>{extraLines.map((key, index) => <div className="extra-line" key={key}><Field label={t("Line {0}", index + 1)} className="full"><input name={`description-${key}`} required maxLength={200} placeholder={t("Description")}/></Field><Field label={t("Quantity")}><input name={`quantity-${key}`} required defaultValue="1" inputMode="decimal" pattern="[0-9]{1,7}([.,][0-9]{1,6})?"/></Field><Field label={t("Unit price ({0})", currency)}><Amount name={`unitPrice-${key}`}/></Field><Field label={t("Tax %")}><input key={`line-rate-${treatment}`} name={`taxRate-${key}`} required defaultValue={defaultRate} inputMode="decimal" pattern="[0-9]{1,3}([.,][0-9]{1,3})?" title={t("A percentage such as 21 or 8.875")}/></Field><button type="button" className="icon-button" aria-label={t("Remove line {0}", index + 1)} onClick={() => setExtraLines(lines => lines.filter(line => line !== key))}><Trash2 size={17}/></button></div>)}</>}<Field label={t("Invoice note")} className="form-note"><textarea name="notes" rows={2} maxLength={4000} placeholder={t("Optional note for your client")}/></Field><p className="form-footnote">{t("You will review the complete document and calculated totals before issuing. Creating a draft reserves its selected time so it can't be invoiced twice.")}</p></Form>;
}
function PaymentForm(props: Props) {
  const invoice = props.state.invoices.find(invoice => invoice.id === props.id)!;
  return <Form {...props} label={t("Record payment")} onSubmit={async data => !!await props.run({ type: 'payment.create', data: { invoiceId: invoice.id, date: text(data, 'date'), amount: decimalText(data, 'amount'), reference: text(data, 'reference') } })}><div className="form-body"><div className="balance-callout"><span>{t("Outstanding on")}{' '}{invoice.number}</span><strong>{money(invoice.outstandingMinor, invoice.currency)}</strong></div><div className="form-grid"><Field label={t("Amount received ({0})", invoice.currency)}><Amount name="amount" value={invoice.outstandingMinor > 0 ? decimal(invoice.outstandingMinor) : ''}/></Field><Field label={t("Receipt date")}><input type="date" name="date" defaultValue={today()} max={today()} required/></Field><Field label={t("Payment reference")} className="full"><input name="reference" placeholder={t("e.g. Bank transfer reference")}/></Field></div><p className="form-footnote">{t("Record the money that actually arrived. A partial payment leaves the remaining balance open. Payments are not revenue; they reduce what is outstanding.")}</p></div></Form>;
}
function CreditForm(props: Props) {
  const invoice = props.state.invoices.find(invoice => invoice.id === props.id)!;
  return <Form {...props} label={t("Create credit note")} onSubmit={async data => !!await props.run({ type: 'credit.create', data: { invoiceId: invoice.id, date: text(data, 'date'), netAmount: decimalText(data, 'netAmount'), reason: text(data, 'reason') } })}><div className="form-grid"><Field label={t("Amount before tax ({0})", invoice.currency)}><Amount name="netAmount"/></Field><Field label={t("Credit date")}><input type="date" name="date" defaultValue={today()} max={today()} required/></Field><Field label={t("Reason for correction")} className="full"><textarea name="reason" required rows={3} maxLength={200} placeholder={t("Describe the agreed correction")}/></Field></div><p className="form-footnote">{t("The credit gets its own number and uses the invoice's original tax rate. It reduces revenue and the balance; a paid invoice may then show an amount to refund.")}</p></Form>;
}

function ExpenseForm(props: Props) {
  const expense = props.state.expenses.find(item => item.id === props.id);
  const [opened] = useState(expense);
  const base = props.state.workspace.currency;
  const [vat, setVat] = useState<ExpenseVat>(expense?.vatTreatment || 'standard');
  const [original, setOriginal] = useState(expense?.originalCurrency || base);
  const file = expense?.attachmentId ? props.state.attachments.find(item => item.id === expense.attachmentId) : undefined;
  return <Form {...props} label={opened ? t("Save changes") : t("Save expense")} onSubmit={async data => {
    if (opened && !expense) throw new Error(t("This expense was deleted in another window."));
    const input: ExpenseInput = { projectId: text(data, 'projectId') || null, date: text(data, 'date'), description: text(data, 'description'), netAmount: decimalText(data, 'netAmount'), taxAmount: vat === 'standard' ? decimalText(data, 'taxAmount') : '0', deductibleTax: checked(data, 'deductibleTax'), supplier: text(data, 'supplier'), supplierInvoiceNumber: text(data, 'supplierInvoiceNumber'), category: text(data, 'category'), country: text(data, 'country'), vatTreatment: vat, paymentMethod: text(data, 'paymentMethod'), notes: text(data, 'notes'), originalCurrency: original, originalAmount: original !== base && text(data, 'originalAmount') ? decimalText(data, 'originalAmount') : null };
    if (expense) return !!await props.run({ type: 'expense.update', data: { ...input, id: expense.id, revision: expense.revision } });
    const upload = data.get('attachment') as File;
    let attachment: Upload | null = null;
    if (upload?.size) {
      if (!['image/png', 'image/jpeg', 'application/pdf'].includes(upload.type)) throw new Error(t("Use an original PNG, JPEG or PDF file."));
      attachment = await fileUpload(upload);
    }
    return !!await props.run({ type: 'expense.create', data: { ...input, attachment } });
  }}><Changed opened={opened} current={expense} noun="expense" fields={[['description', t("Description")], ['netMinor', t("Net amount"), value => money(Number(value), base)], ['date', t("Date"), value => date(String(value))]]}/><div className="form-grid"><Field label={t("Belongs to")} className="full" hint={t("Project costs reduce that project's contribution. General costs count toward your overall result and VAT.")}><select name="projectId" defaultValue={expense ? expense.projectId ?? '' : props.projectId ?? ''}><option value="">{t("General business cost · no project")}</option>{props.state.projects.map(project => <option value={project.id} key={project.id}>{project.name} · {props.state.clients.find(client => client.id === project.clientId)?.name}</option>)}</select></Field><Field label={t("Description")} className="full"><input name="description" required defaultValue={expense?.description} placeholder={t("e.g. Design software, September")} maxLength={200}/></Field><Field label={t("Supplier")}><input name="supplier" defaultValue={expense?.supplier} maxLength={200} placeholder={t("Who sent the bill?")}/></Field><Field label={t("Supplier invoice number")}><input name="supplierInvoiceNumber" defaultValue={expense?.supplierInvoiceNumber} maxLength={100} placeholder={t("Optional")}/></Field><Field label={t("Category")}><input name="category" list="expense-categories" defaultValue={expense?.category} maxLength={60} placeholder={t("e.g. Software")}/><Suggestions id="expense-categories" values={[...EXPENSE_CATEGORIES, ...props.state.expenses.map(item => item.category)]}/></Field><Field label={t("Supplier country")}><Country optional value={expense?.country ?? ''}/></Field><Field label={t("Expense date")}><input type="date" name="date" defaultValue={expense?.date || today()} max={today()} required/></Field><Field label={t("Paid with")}><input name="paymentMethod" list="payment-methods" defaultValue={expense?.paymentMethod} maxLength={60} placeholder={t("e.g. Credit card")}/><Suggestions id="payment-methods" values={PAYMENT_METHODS}/></Field><Field label={t("VAT treatment")} className="full"><select value={vat} onChange={event => setVat(event.target.value as ExpenseVat)}>{EXPENSE_VAT.map(value => <option key={value} value={value}>{expenseVatLabels[value]}</option>)}</select></Field><Field label={t("Amount before VAT ({0})", base)}><Amount name="netAmount" value={expense ? decimal(expense.netMinor) : ''}/></Field>{vat === 'standard' ? <Field label={t("VAT charged ({0})", base)}><Amount name="taxAmount" value={expense ? decimal(expense.taxMinor) : '0.00'}/></Field> : <div className="field-note">{vat === 'none' ? t("No VAT on this cost.") : t("You declare {0}% VAT yourself in your return; it is usually deductible in the same return.", props.state.business.defaultTaxRate)}</div>}<Field label={t("Original currency")} hint={t("If you paid in another currency, book the amounts above in {0}.", base)}><Currency value={original} onChange={setOriginal}/></Field>{original !== base && <Field label={t("Amount charged ({0})", original)} hint={t("As on the supplier invoice or card statement.")}><Amount name="originalAmount" required={false} value={expense?.originalAmountMinor != null ? decimal(expense.originalAmountMinor) : ''}/></Field>}<Field label={t("Notes")} className="full"><input name="notes" defaultValue={expense?.notes} maxLength={4000} placeholder={t("Optional, e.g. card fee or exchange surcharge")}/></Field></div><div className="checks"><CheckField name="deductibleTax" defaultChecked={expense?.deductibleTax ?? !props.state.business.smallBusinessScheme}>{t("VAT is deductible for this business")}</CheckField></div>{expense ? <p className="form-footnote">{file ? t("Attachment “{0}” stays linked.", file.name) : t("No attachment is linked.")}{' '}{t("To replace an attachment, delete this expense and record it again.")}</p> : <Field label={t("Original receipt or invoice (optional)")} hint={t("PNG, JPEG or PDF · up to 5 MB · stored in this workspace and its backups")} className="file-field"><input name="attachment" type="file" accept="image/png,image/jpeg,application/pdf"/></Field>}<p className="form-footnote">{t("When VAT is not deductible, it is included in the cost. A project's contribution updates once its costs are confirmed complete.")}</p></Form>;
}
function SettingsForm(props: Props) {
  const business = props.state.business;
  const [opened] = useState(business);
  // The server refuses a currency change once amounts exist; the form says so up front.
  const locked = [props.state.clients, props.state.projects, props.state.invoices, props.state.expenses].some(list => list.length > 0);
  return <Form {...props} label={t("Save settings")} onSubmit={async data => {
    const file = data.get('logo') as File;
    let logo: Upload | null | undefined;
    if (checked(data, 'removeLogo')) logo = null;
    else if (file?.size) { if (!['image/png', 'image/jpeg'].includes(file.type)) throw new Error(t("Use a PNG or JPEG logo.")); logo = await fileUpload(file); }
    const input: Omit<BusinessProfile, 'logoId' | 'nextInvoiceNumber'> & { nextInvoiceNumber?: number; logo?: Upload | null } = { name: text(data, 'name'), address: text(data, 'address'), country: text(data, 'country'), region: text(data, 'region'), legalForm: text(data, 'legalForm'), taxRegistered: checked(data, 'taxRegistered'), taxId: text(data, 'taxId'), registrationId: text(data, 'registrationId'), currency: locked ? business.currency : text(data, 'currency'), invoicePrefix: text(data, 'invoicePrefix'), defaultTaxRate: decimalText(data, 'defaultTaxRate'), paymentInstructions: text(data, 'paymentInstructions'), revision: business.revision, nextInvoiceNumber: Number(text(data, 'nextInvoiceNumber')), vatFrequency: text(data, 'vatFrequency') as BusinessProfile['vatFrequency'], smallBusinessScheme: checked(data, 'smallBusinessScheme') };
    if (logo !== undefined) input.logo = logo;
    return !!await props.run({ type: 'business.update', data: input });
  }}><Changed opened={opened} current={business} noun="business profile" fields={[['name', t("Business name")], ['address', t("Address")], ['country', t("Country"), value => country(String(value))], ['taxRegistered', t("Tax registered")], ['taxId', t("Tax ID")], ['registrationId', t("Registration ID")], ['invoicePrefix', t("Invoice prefix")], ['nextInvoiceNumber', t("Next invoice number")], ['defaultTaxRate', t("Default tax rate")], ['paymentInstructions', t("Payment instructions")], ['logoId', t("Logo"), value => value ? 'replaced' : 'removed']]}/><div className="form-grid"><Field label={t("Business name")} className="full"><input name="name" required maxLength={200} defaultValue={business.name}/></Field><Field label={t("Business address")} className="full"><textarea name="address" rows={3} maxLength={4000} defaultValue={business.address} placeholder={t("Full street address, postal code and city")}/></Field><Field label={t("Business country")}><Country value={business.country}/></Field><Field label={t("Region / state")}><input name="region" maxLength={200} defaultValue={business.region}/></Field><Field label={t("Legal form")}><input name="legalForm" maxLength={200} defaultValue={business.legalForm} placeholder={t("e.g. Sole proprietor")}/></Field><Field label={t("Base currency")} hint={locked ? t("Fixed once records exist. Invoices can still use another currency; create a new workspace to change bookkeeping currency.") : t("Your bookkeeping currency. Invoices can use any currency.")}><Currency name="currency" defaultValue={business.currency} disabled={locked}/></Field><Field label={t("Tax / VAT registration ID")}><input name="taxId" maxLength={100} defaultValue={business.taxId} placeholder={t("NL123456789B01")}/></Field><Field label={t("Business registration ID")}><input name="registrationId" maxLength={100} defaultValue={business.registrationId} placeholder={t("KvK number where required")}/></Field></div><div className="checks"><CheckField name="taxRegistered" defaultChecked={business.taxRegistered}>{t("This business is registered for tax / VAT")}</CheckField><CheckField name="smallBusinessScheme" defaultChecked={business.smallBusinessScheme}><span>{t("Small business scheme applies (e.g. Dutch KOR) · no VAT charged or reclaimed")}</span></CheckField></div><div className="form-grid"><Field label={t("Default tax rate (%)")} hint={t("Also used for reverse-charged purchases.")}><input name="defaultTaxRate" defaultValue={business.defaultTaxRate} required inputMode="decimal" pattern="[0-9]{1,3}([.,][0-9]{1,3})?" title={t("A percentage such as 21 or 8.875")}/></Field><Field label={t("VAT returns")}><select name="vatFrequency" defaultValue={business.vatFrequency}><option value="quarterly">{t("Every quarter")}</option><option value="monthly">{t("Every month")}</option><option value="annual">{t("Once a year")}</option></select></Field><Field label={t("Invoice number prefix")} hint={t("“CN” is reserved for credit notes.")}><input name="invoicePrefix" defaultValue={business.invoicePrefix} required maxLength={20} pattern="[A-Za-z0-9\-]{1,20}" title={t("Letters, numbers and hyphens")}/></Field><Field label={t("Next invoice number")} hint={t("Used only for the next issue; existing numbers stay fixed.")}><input name="nextInvoiceNumber" type="number" min="1" step="1" defaultValue={business.nextInvoiceNumber} required/></Field><Field label={t("Own logo")} hint={t("PNG or JPEG · up to 5 MB")}><input name="logo" type="file" accept="image/png,image/jpeg"/></Field>{business.logoId && <div className="logo-preview full"><img src={`/api/attachments/${business.logoId}`} alt={t("Current business logo")}/><CheckField name="removeLogo">{t("Remove current logo")}</CheckField></div>}<Field label={t("Payment instructions")} className="full"><textarea name="paymentInstructions" maxLength={4000} defaultValue={business.paymentInstructions} rows={3} placeholder={t("Bank details and payment reference instructions")}/></Field></div><div className="notice"><strong>{t("Current issuance scope")}</strong><p>{t("Final invoices can be issued by VAT registered Netherlands suppliers keeping their books in EUR: Dutch customers at 21% or 9%, EU business customers with reverse charge (0%, their VAT ID required) and customers outside the EU (0%). Invoices may use any currency with an exchange rate. Other cases remain usable drafts. Check your registration, transaction type and invoice requirements.")}</p><a href="https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/zakelijk/btw/administratie_bijhouden/facturen_maken/factuureisen/" target="_blank" rel="noreferrer" className="text-link">{t("Official NL invoice requirements")}{' '}<ExternalLink size={13}/></a></div><p className="form-footnote">{t("Issued invoices preserve a snapshot of these details and your logo. This app does not file tax returns.")}</p></Form>;
}

function WorkspaceForm(props: Props) {
  const [tab, setTab] = useState('backup');
  const [backup, setBackup] = useState<{ status: 'idle' | 'working' | 'done' | 'failed'; text: string }>({ status: 'idle', text: '' });
  const [switchError, setSwitchError] = useState('');
  const { workspace } = props.state;
  async function downloadBackup() {
    setBackup({ status: 'working', text: '' });
    try {
      const file = await download('/api/backup', 'billable-backup.zip');
      setBackup({ status: 'done', text: t("{0} ({1}) was handed to your browser at {2}. Check your downloads folder, then keep a copy off this computer.", file.name, bytes(file.size), new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })) });
    } catch (error) { setBackup({ status: 'failed', text: t("No backup was created. {0}", error instanceof Error ? t(error.message) : '') }); }
  }
  return <div className="workspace-form"><div className="tabs" role="tablist">{[['backup', t("Backup & restore")], ['switch', t("Workspaces")], ['new', t("New workspace")]].map(([key, value]) => <button key={key} role="tab" aria-selected={tab === key} className={tab === key ? 'active' : ''} onClick={() => setTab(key)}>{value}</button>)}</div>{tab === 'backup' ? <><div className="backup-download"><div className="backup-icon"><Download size={25}/></div><div><h3>{t("Take your whole workspace with you.")}</h3><p>“{workspace.name}” · {workspace.demo ? t("fictional demo") : t("your records")} · {workspace.currency}{t(". All records, invoice snapshots, attachments and logos in one ZIP.")}</p></div><Button data-autofocus icon={Download} onClick={() => void downloadBackup()} disabled={backup.status === 'working'}>{backup.status === 'working' ? t("Preparing…") : t("Download backup")}</Button></div>{backup.status === 'done' && <p className="backup-status ok" role="status"><CheckCircle2 size={16}/>{backup.text}</p>}{backup.status === 'failed' && <p className="backup-status failed" role="alert"><AlertCircle size={16}/>{backup.text}</p>}<p className="form-footnote">{t("The backup contains business details, invoices and attachments, unencrypted. Save closed backup files in OneDrive or Google Drive if you like; keep the active database local. JSON analysis exports do not replace a full backup.")}</p><a href="/api/export" className="text-link export-link" download>{t("Download JSON analysis export")}{' '}<Download size={14}/></a><Form {...props} label={t("Restore into a new workspace")} onSubmit={async data => {
    const file = data.get('backup') as File;
    if (!file?.size) throw new Error(t("Choose a full backup ZIP first."));
    const upload = await fileUpload(file, 128 * 1024 * 1024);
    return !!await props.run({ type: 'backup.restore', data: { name: text(data, 'name'), base64: upload.base64 } });
  }}><div className="form-section-heading"><h3>{t("Restore a full backup")}</h3></div><div className="form-grid"><Field label={t("Restored workspace name")} className="full"><input name="name" defaultValue={t("{0} restored", workspace.name)} required maxLength={120}/></Field><Field label={t("Backup ZIP")} className="full"><input name="backup" type="file" accept=".zip,application/zip" required/></Field></div><p className="form-footnote">{t("The backup is checked completely before importing. Restore creates and opens a new workspace; “")}{workspace.name}{t("” stays available under Workspaces. A running timer in the backup is not restored.")}</p></Form></> : tab === 'switch' ? <div className="workspace-list">{switchError && <p className="form-error" role="alert"><AlertCircle size={16}/>{switchError}</p>}{props.state.workspaces.map(item => <button key={item.id} disabled={props.busy || item.id === workspace.id} onClick={async () => { setSwitchError(''); try { if (await props.run({ type: 'workspace.switch', data: { id: item.id } })) props.onClose(); } catch (error) { setSwitchError(error instanceof Error ? t(error.message) : t("Could not open this workspace.")); } }}><span className="workspace-avatar">{item.demo ? 'D' : item.name[0]}</span><span><strong>{item.name}</strong><small>{item.demo ? t("Fictional demo data") : t("Your own administration")} · {item.currency}</small></span>{item.id === workspace.id ? <><small className="muted">{t("Open now")}</small><Check size={18}/></> : <span className="text-link">{t("Open")}</span>}</button>)}</div> : <Form {...props} label={t("Create workspace")} onSubmit={async data => !!await props.run({ type: 'workspace.create', data: { name: text(data, 'name'), currency: text(data, 'currency'), demo: checked(data, 'demo') } })}><div className="form-grid"><Field label={t("Workspace name")} className="full"><input name="name" required placeholder={t("e.g. My studio")} maxLength={120}/></Field><Field label={t("Base currency")} className="full" hint={t("Your bookkeeping currency. Invoices can use any currency.")}><Currency name="currency" defaultValue="EUR"/></Field></div><div className="checks"><CheckField name="demo"><strong>{t("Start with fictional demo records")}</strong><small>{t("Leave unchecked for your own empty administration.")}</small></CheckField></div><p className="form-footnote">{t("One business and one base currency per workspace. Demo records are clearly separated from your own work. Your current workspace stays available.")}</p></Form>}</div>;
}

function ConfirmForm(props: Props & { type: ModalName }) {
  const { state, type, id, run } = props;
  const names: Record<string, [string, string]> = { deleteTime: [t("Delete this time entry?"), t("This removes the entry from actual project effort.")], deleteExpense: [t("Delete this expense?"), t("This removes the recorded cost and its stored attachment from this workspace. Earlier backups keep their copy.")], deleteDraft: [t("Delete this draft?"), t("All time reserved by this draft will become available again. No number is used.")], issue: [t("Ready to issue this invoice?"), t("It gets the next invoice number, and its prices, client details and business details are frozen. Use credit notes for later corrections. Issuing does not send it.")], reversePayment: [t("Reverse this payment?"), t("A linked negative record is added. The original receipt stays in the history.")] };
  return <Form {...props} label={type === 'issue' ? t("Issue invoice") : type === 'reversePayment' ? t("Record reversal") : t("Delete record")} onSubmit={async data => {
    if (type === 'deleteTime') { const record = state.timeEntries.find(entry => entry.id === id); if (!record) throw new Error(t("This entry was already deleted.")); return !!await run({ type: 'time.delete', data: { id: record.id, revision: record.revision } }); }
    if (type === 'deleteExpense') { const record = state.expenses.find(entry => entry.id === id); if (!record) throw new Error(t("This expense was already deleted.")); return !!await run({ type: 'expense.delete', data: { id: record.id, revision: record.revision } }); }
    if (type === 'reversePayment') return !!await run({ type: 'payment.reverse', data: { id: id!, date: text(data, 'date'), reason: text(data, 'reason') } });
    const invoice = state.invoices.find(entry => entry.id === id);
    if (!invoice) throw new Error(t("This invoice no longer exists."));
    return !!await run({ type: type === 'issue' ? 'invoice.issue' : 'invoice.deleteDraft', data: { id: invoice.id, revision: invoice.revision } });
  }}><div className="confirm-body"><h3>{names[type][0]}</h3><p>{names[type][1]}</p>{type === 'reversePayment' && <div className="form-grid"><Field label={t("Reversal date")}><input name="date" type="date" defaultValue={today()} max={today()} required/></Field><Field label={t("Reason")} className="full"><input name="reason" required maxLength={200} placeholder={t("e.g. Duplicate receipt entered")}/></Field></div>}{type === 'issue' && <CheckField required>{t("I checked the document and that this tax treatment applies.")}</CheckField>}</div></Form>;
}

function VatFilingForm(props: Props) {
  const period = props.state.vatPeriods.find(item => item.period === props.id);
  const [status, setStatus] = useState<VatFiling['status']>(period?.filing?.status || 'filed');
  if (!period) return <div className="form-body"><p>{t("This VAT period is no longer available.")}</p><div className="form-actions"><Button variant="secondary" onClick={props.onClose}>{t("Close")}</Button></div></div>;
  const currency = props.state.workspace.currency;
  return <Form {...props} label={t("Save status")} onSubmit={async data => !!await props.run({ type: 'vat.filing', data: { period: period.period, status, filedOn: status === 'filed' ? text(data, 'filedOn') || null : null, note: text(data, 'note') } })}><div className="form-body"><div className="balance-callout"><span>{period.period} · {period.balanceMinor < 0 ? t("to reclaim") : t("to pay")}</span><strong>{money(Math.abs(period.balanceMinor), currency)}</strong></div><div className="form-grid"><Field label={t("Status")}><select value={status} onChange={event => setStatus(event.target.value as VatFiling['status'])}><option value="todo">{t("To do")}</option><option value="filed">{t("Filed")}</option><option value="not-applicable">{t("Not applicable")}</option></select></Field>{status === 'filed' && <Field label={t("Filed on")}><input type="date" name="filedOn" defaultValue={period.filing?.filedOn || today()} max={today()}/></Field>}<Field label={t("Note")} className="full"><input name="note" maxLength={4000} defaultValue={period.filing?.note} placeholder={t("e.g. reference or paid on")}/></Field></div><p className="form-footnote">{t("Billable does not submit returns. Record what you filed in your tax portal so every period has a clear status.")}</p></div></Form>;
}

const titles: Record<ModalName, string> = { client: t("Client details"), project: t("Project details"), time: t("Put your time on the page."), timer: t("Start a focused session."), timerStop: t("Review the actual work."), draft: t("From work to invoice."), payment: t("A payment received."), credit: t("Correct with a credit note."), expense: t("Record a cost."), vatFiling: t("VAT return status."), settings: t("Your business, your details."), workspace: t("Your work. Your workspace."), deleteTime: t("Confirm deletion"), deleteExpense: t("Confirm deletion"), deleteDraft: t("Confirm deletion"), reversePayment: t("Payment correction"), issue: t("Issue this document") };
export function ActiveModal(props: Props & { type: ModalName }) {
  const forms: Partial<Record<ModalName, React.ComponentType<Props>>> = { client: ClientForm, project: ProjectForm, time: TimeForm, timer: TimerForm, timerStop: StopTimerForm, draft: DraftForm, payment: PaymentForm, credit: CreditForm, expense: ExpenseForm, settings: SettingsForm, workspace: WorkspaceForm, vatFiling: VatFilingForm };
  const Component = forms[props.type];
  // Forms show failures next to the retained input instead of in a toast.
  const inline: Run = command => props.run(command, { inline: true });
  return <Modal title={titles[props.type]} onClose={props.onClose} wide={['draft', 'settings', 'workspace', 'expense'].includes(props.type)}>{Component ? <Component {...props} run={inline}/> : <ConfirmForm {...props} run={inline}/>}</Modal>;
}
